/// Finds all duplicate elements in an array where values are in the range [1, n]
/// (n = array length) and each value appears **at most twice**.
/// Uses O(1) extra space via index-negation.
///
/// Returns a Vec of values that appear exactly twice (order follows the
/// position of the second occurrence). The input array is restored to its
/// original state before returning.
///
/// # Panics
/// Panics if any element is outside [1, n].
///
/// # Algorithm
/// Two passes over the array:
/// 1. For each element, negate `nums[abs(val) - 1]`. A double-negative means
///    `abs(val)` was already seen → duplicate.
/// 2. Restore every entry to its original positive value.
///
/// Each value appears at most twice, so the sign flips at most once per index,
/// keeping the logic sound.
pub fn find_duplicates(nums: &mut [i32]) -> Vec<i32> {
    let n = nums.len();
    let mut result = Vec::new();

    // Pass 1: detect duplicates via negation
    for i in 0..n {
        let idx = nums[i].unsigned_abs() as usize;
        assert!(idx >= 1 && idx <= n, "element {} out of range [1, {}]", nums[i], n);
        if nums[idx - 1] < 0 {
            result.push(idx as i32);
        } else {
            nums[idx - 1] = -nums[idx - 1];
        }
    }

    // Pass 2: restore original values
    for num in nums.iter_mut() {
        *num = num.abs();
    }

    result
}

fn main() {
    println!("Run with: rustc --test find_duplicates.rs && ./find_duplicates");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_no_duplicates() {
        let mut arr = [1, 2, 3, 4, 5];
        assert_eq!(find_duplicates(&mut arr), vec![]);
        assert_eq!(arr, [1, 2, 3, 4, 5]);
    }

    #[test]
    fn test_single_duplicate() {
        let mut arr = [1, 2, 3, 2];
        assert_eq!(find_duplicates(&mut arr), vec![2]);
        assert_eq!(arr, [1, 2, 3, 2]);
    }

    #[test]
    fn test_multiple_duplicates() {
        let mut arr = [4, 3, 2, 7, 8, 2, 3, 1];
        let mut result = find_duplicates(&mut arr);
        result.sort();
        assert_eq!(result, vec![2, 3]);
        assert_eq!(arr, [4, 3, 2, 7, 8, 2, 3, 1]);
    }

    #[test]
    fn test_two_elements_same() {
        let mut arr = [1, 1];
        assert_eq!(find_duplicates(&mut arr), vec![1]);
        assert_eq!(arr, [1, 1]);
    }

    #[test]
    fn test_single_element() {
        let mut arr = [1];
        assert_eq!(find_duplicates(&mut arr), vec![]);
        assert_eq!(arr, [1]);
    }

    #[test]
    fn test_duplicates_at_ends() {
        let mut arr = [3, 2, 1, 5, 4, 3];
        let mut result = find_duplicates(&mut arr);
        result.sort();
        assert_eq!(result, vec![3]);
        assert_eq!(arr, [3, 2, 1, 5, 4, 3]);
    }

    #[test]
    fn test_every_element_duplicated() {
        let mut arr = [2, 1, 2, 1];
        let mut result = find_duplicates(&mut arr);
        result.sort();
        assert_eq!(result, vec![1, 2]);
        assert_eq!(arr, [2, 1, 2, 1]);
    }

    #[test]
    fn test_large_array() {
        let mut arr: Vec<i32> = (1..=1000).collect();
        arr.push(500);
        let result = find_duplicates(&mut arr);
        assert_eq!(result, vec![500]);
    }

    #[test]
    fn test_array_is_restored() {
        let original = [5, 1, 2, 3, 4, 5];
        let mut arr = original;
        find_duplicates(&mut arr);
        assert_eq!(arr, original);
    }

    #[test]
    fn test_multiple_scattered_duplicates() {
        let mut arr = [1, 2, 3, 4, 5, 1, 3, 5];
        let mut result = find_duplicates(&mut arr);
        result.sort();
        assert_eq!(result, vec![1, 3, 5]);
        assert_eq!(arr, [1, 2, 3, 4, 5, 1, 3, 5]);
    }

    #[test]
    fn test_adjacent_duplicates() {
        let mut arr = [3, 3, 1, 1, 2, 2];
        let mut result = find_duplicates(&mut arr);
        result.sort();
        assert_eq!(result, vec![1, 2, 3]);
        assert_eq!(arr, [3, 3, 1, 1, 2, 2]);
    }

    #[test]
    #[should_panic(expected = "out of range")]
    fn test_out_of_range_value() {
        let mut arr = [1, 2, 6];
        find_duplicates(&mut arr);
    }

    #[test]
    #[should_panic(expected = "out of range")]
    fn test_zero_value() {
        let mut arr = [0, 1, 2];
        find_duplicates(&mut arr);
    }

    #[test]
    fn test_n_equals_one_no_dup() {
        let mut arr = [1];
        assert_eq!(find_duplicates(&mut arr), vec![]);
    }

    #[test]
    fn test_n_equals_two_no_dup() {
        let mut arr = [1, 2];
        assert_eq!(find_duplicates(&mut arr), vec![]);
    }
}
